Here's a debounced search in plain JavaScript and in React. Both also cancel in-flight requests, so a slow, stale response can't overwrite a newer one.

## Vanilla JavaScript

```html
<input id="search" type="search" placeholder="Search…" />
<ul id="results"></ul>
```

```js
function debounce(fn, delay = 300) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

const input = document.getElementById('search');
const resultsEl = document.getElementById('results');
let controller; // aborts the previous request

async function search(query) {
  controller?.abort();
  if (!query.trim()) {
    resultsEl.innerHTML = '';
    return;
  }

  controller = new AbortController();
  try {
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
      signal: controller.signal,
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    resultsEl.innerHTML = data.map(item => `<li>${item.name}</li>`).join('');
  } catch (err) {
    if (err.name !== 'AbortError') console.error('Search failed:', err);
  }
}

const debouncedSearch = debounce(search, 300);
input.addEventListener('input', e => debouncedSearch(e.target.value));
```

## React (custom hook)

```jsx
import { useEffect, useState } from 'react';

function useDebouncedValue(value, delay = 300) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(id); // reset timer on every keystroke
  }, [value, delay]);
  return debounced;
}

export function SearchBox() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const [error, setError] = useState(null);
  const debouncedQuery = useDebouncedValue(query, 300);

  useEffect(() => {
    if (!debouncedQuery.trim()) {
      setResults([]);
      return;
    }
    const controller = new AbortController();

    fetch(`/api/search?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then(data => {
        setResults(data);
        setError(null);
      })
      .catch(err => {
        if (err.name !== 'AbortError') setError(err.message);
      });

    return () => controller.abort(); // cancel when query changes or unmounts
  }, [debouncedQuery]);

  return (
    <div>
      <input
        type="search"
        value={query}
        onChange={e => setQuery(e.target.value)}
        placeholder="Search…"
      />
      {error && <p role="alert">{error}</p>}
      <ul>
        {results.map(r => <li key={r.id}>{r.name}</li>)}
      </ul>
    </div>
  );
}
```

## How it works

- **Debounce:** each keystroke resets the timer, so the API is only called after the user has stopped typing for 300 ms. Typing "laptop" quickly sends 1 request instead of 6.
- **Input stays responsive:** in React, `query` updates on every keystroke and only `debouncedQuery` triggers the fetch.
- **Cancellation:** `AbortController` drops the previous request, which prevents out-of-order responses from showing results for an old query.
- **Empty input:** clears results without calling the API.
- **Delay:** 250–400 ms usually feels right. Go lower for fast local APIs and higher for expensive ones.

If you use lodash, `_.debounce` can replace the hand-written helper. In React, wrap it in `useMemo` or `useRef` so it isn't recreated on every render.
